export async function seedDecks() {
  const existing = await db.select().from(vocab_decks).limit(1)
  if (existing.length > 0) {
    console.log('[seed] vocab_decks already populated — clearing and re-seeding')
    await db.delete(vocab_deck_words)
    await db.delete(vocab_decks)
  }

  for (const def of DECKS) {
    const [deck] = await db.insert(vocab_decks).values({
      title: def.title,
      description: def.description,
      level: def.level,
      topic: def.topic,
      word_count: def.words.length,
    }).returning()

    await db.insert(vocab_deck_words).values(
      def.words.map((w, i) => ({ deck_id: deck!.id, ...w, sort_order: i }))
    )

    console.log(`[seed] deck "${def.title}" (${def.level}) — ${def.words.length} words`)
  }

  console.log(`[seed] ${DECKS.length} decks seeded`)
}

// Allow running directly: tsx src/db/seedDecks.ts
if (process.argv[1]?.endsWith('seedDecks.ts') || process.argv[1]?.endsWith('seedDecks.js')) {
  import('dotenv/config').then(() => seedDecks()).catch(e => { console.error(e); process.exit(1) })
}
